const { withAndroidStyles, withDangerousMod, AndroidConfig } = require("expo/config-plugins");
const fs = require("node:fs/promises");
const path = require("node:path");

module.exports = function withNeutralPickers(config) {
  // Both framework widgets read state_activated from a ColorStateList.
  // Keep this resource outside values/colors.xml so light/night solid colors
  // generated by the datetimepicker plugin cannot replace the selected state.
  config = withDangerousMod(config, ["android", async (config) => {
    const directory = path.join(config.modRequest.platformProjectRoot, "app/src/main/res/color");
    await fs.mkdir(directory, { recursive: true });
    await fs.writeFile(path.join(directory, "notiva_picker_value_text.xml"), `<?xml version="1.0" encoding="utf-8"?>
<selector xmlns:android="http://schemas.android.com/apk/res/android">
  <item android:state_activated="true" android:color="#FFFFFF" />
  <item android:color="#171329" />
</selector>
`);
    // An explicit activated state prevents DatePicker's legacy compatibility
    // path from dimming the inactive header label with disabledAlpha.
    await fs.writeFile(path.join(directory, "notiva_date_picker_header_text.xml"), `<?xml version="1.0" encoding="utf-8"?>
<selector xmlns:android="http://schemas.android.com/apk/res/android">
  <item android:state_activated="true" android:color="#FFFFFF" />
  <item android:color="#FFFFFF" />
</selector>
`);
    return config;
  }]);
  return withAndroidStyles(config, (config) => {
    const styles = config.modResults.resources.style || [];

    // Remove stale / unsupported attributes from previous attempts.
    for (const style of styles) {
      if (
        style.$.name === "TimePickerTheme" ||
        style.$.name === "NotivaDatePicker"
      ) {
        style.item = (style.item || []).filter(
          (item) => item.$.name !== "android:headerTextColor"
        );
      }

      if (style.$.name === "TimePickerTheme") {
        style.item = (style.item || []).filter(
          (item) => item.$.name !== "android:amPmTextColor"
        );
      }

      if (style.$.name === "NotivaTimePickerDialog") {
        const oldOverrides = [
          "android:windowBackground",
          "android:textColorPrimary",
          "android:textColorSecondary",
          "android:textColorPrimaryInverse",
          "android:textColorSecondaryInverse",
        ];

        style.item = (style.item || []).filter(
          (item) => !oldOverrides.includes(item.$.name)
        );
      }

      if (style.$.name === "NotivaDatePicker") {
        style.item = (style.item || []).filter(
          (item) => item.$.name !== "android:headerBackground"
        );
      }
    }

    const setStyleValues = (name, parent, values) => {
      for (const [attribute, value] of Object.entries(values)) {
        config.modResults =
          AndroidConfig.Styles.assignStylesValue(config.modResults, {
            add: true,
            parent: {
              name,
              parent,
            },
            name: attribute,
            value,
          });
      }
    };

    // =========================
    // TIME PICKER
    // =========================

    setStyleValues(
      "TimePickerTheme",
      "android:Widget.Material.Light.TimePicker",
      {
        "android:numbersTextColor": "@color/notiva_picker_value_text",
        "android:numbersInnerTextColor": "@color/notiva_picker_value_text",
      }
    );

    setStyleValues(
      "NotivaTimePickerDialog",
      "Theme.AppCompat.Light.Dialog",
      {
        colorAccent: "#4D3FE6",
        "android:colorAccent": "#4D3FE6",
        "android:timePickerStyle": "@style/TimePickerTheme",
      }
    );

    config.modResults =
      AndroidConfig.Styles.assignStylesValue(config.modResults, {
        add: true,
        parent: AndroidConfig.Styles.getAppThemeGroup(),
        name: "android:timePickerDialogTheme",
        value: "@style/NotivaTimePickerDialog",
      });

    // =========================
    // DATE PICKER
    // =========================

    setStyleValues("NotivaCalendarDayText", "android:TextAppearance.Material.Caption", {
      "android:textColor": "@color/notiva_picker_value_text",
    });
    setStyleValues("NotivaCalendarView", "android:Widget.Material.Light.CalendarView", {
      "android:dateTextAppearance": "@style/NotivaCalendarDayText",
    });
    setStyleValues("NotivaDatePickerHeaderText", "", {
      "android:textColor": "@color/notiva_date_picker_header_text",
    });

    setStyleValues(
      "NotivaDatePicker",
      "android:Widget.Material.Light.DatePicker",
      {
        "android:headerBackground": "#4D3FE6",
        // Public compatibility attribute: the calendar delegate applies this
        // text color to BOTH the year and the selected month/day header.
        "android:headerMonthTextAppearance": "@style/NotivaDatePickerHeaderText",
      }
    );

    setStyleValues(
      "DatePickerDialogTheme",
      "Theme.AppCompat.Light.Dialog",
      {
        "android:datePickerStyle": "@style/NotivaDatePicker",
        "android:calendarViewStyle": "@style/NotivaCalendarView",
        "android:textColorPrimaryInverse": "#171329",
        "android:textColorSecondaryInverse": "#797487",
      }
    );

    config.modResults =
      AndroidConfig.Styles.assignStylesValue(config.modResults, {
        add: true,
        parent: AndroidConfig.Styles.getAppThemeGroup(),
        name: "android:datePickerDialogTheme",
        value: "@style/DatePickerDialogTheme",
      });

    return config;
  });
};
